#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ZIP=""
if [[ -f "$ROOT/dist/manifest.json" ]]; then
  VERSION="$(node -p "require('$ROOT/dist/manifest.json').version" 2>/dev/null || true)"
  [[ -n "${VERSION:-}" ]] && ZIP="$ROOT/release/tab-organizer-v${VERSION}.zip"
fi

banner "Chrome Web Store publish (Tab Organizer)"

# ── 1. Security gate ─────────────────────────────────────────────────────
stage "Security gate (0.3.21 cleared)"
say "PR #3 security fixes are on main: sender check, no tabUrl in activity,"
say "production sweep diag without samples. Rebuild ZIP if you changed code since."
step "Confirm you will use release/tab-organizer-v0.3.21.zip (or newer) for upload."
if ! confirm "Security gate is clear and I will upload 0.3.21+"; then
  warn "Stop and rebuild from main before continuing."
  pause "Press Enter to continue prep without submitting."
fi

# ── 2. Developer account ($5) ────────────────────────────────────────────
stage "Chrome Web Store developer account (\$5 one-time)"
say "Google requires a one-time developer registration fee."
open_url "https://chrome.google.com/webstore/devconsole"
step "Sign in with the Google account that will own the listing."
step "Accept the developer agreement if prompted."
step "Pay the one-time \$5 registration fee when asked (Google payments)."
pause "Press Enter after the developer console loads for your account."

# ── 3. 2FA ───────────────────────────────────────────────────────────────
stage "Enable 2-Step Verification"
say "Chrome Web Store publishing expects 2FA on the publisher Google account."
open_url "https://myaccount.google.com/signinoptions/two-step-verification"
step "Turn on 2-Step Verification if it is not already on."
pause "Press Enter when 2FA is enabled (or already was)."

# ── 4. Privacy policy URL ────────────────────────────────────────────────
stage "Host the privacy policy"
say "Draft lives at docs/privacy-policy.md — CWS needs a public HTTPS URL."
open_url "https://github.com/jenildesai25/tab-organizer/blob/main/docs/privacy-policy.md"
step "Publish that text (GitHub Pages, a public docs site, or equivalent)."
step "Open the live URL in a private window and confirm it loads (no login wall)."
ask CWS_PRIVACY_POLICY_URL "Paste the live privacy policy URL:"
write_env CWS_PRIVACY_POLICY_URL "$CWS_PRIVACY_POLICY_URL"

# ── 5. Screenshots ───────────────────────────────────────────────────────
stage "Screenshots (required)"
say "CWS needs ≥1 screenshot at 1280×800 or 640×400 (PNG or JPEG)."
step "Capture the popup with Organize / Auto-group new tabs visible."
step "Recommended: dashboard Rules with 2–3 example rules."
step "Recommended: Groups or Activity view."
note "Local UI references: .scratch/ui-mock/shots/ (resize/re-capture for store sizes)."
pause "Press Enter when screenshot files are ready on disk."

# ── 6. Build / locate ZIP ────────────────────────────────────────────────
stage "Store package ZIP"
say "Upload must be production dist/ only (no node_modules, no source)."
if [[ -n "$ZIP" && -f "$ZIP" ]]; then
  note "Found: $ZIP"
else
  warn "ZIP not found yet — will build next if you confirm."
fi
if confirm "Run npm run package:cws now to rebuild the ZIP?"; then
  (cd "$ROOT" && npm run package:cws)
  VERSION="$(node -p "require('./dist/manifest.json').version")"
  ZIP="$ROOT/release/tab-organizer-v${VERSION}.zip"
fi
if [[ -n "${ZIP:-}" && -f "$ZIP" ]]; then
  say "Upload this file: $ZIP"
  write_env CWS_PACKAGE_ZIP "$ZIP"
else
  warn "No ZIP on disk. Run: npm run package:cws"
fi
pause "Press Enter when the ZIP path is confirmed."

# ── 7. Upload + listing copy ─────────────────────────────────────────────
stage "Create item and paste listing copy"
open_url "https://chrome.google.com/webstore/devconsole"
step "Click New item → upload the ZIP from the previous stage."
step "Open CHROMEWEBSTORE.md and paste:"
step "  Short description, Detailed description, Category (Productivity)."
step "Upload store icon if asked (icons/icon-128.png) and your screenshots."
note "Copy source: $ROOT/CHROMEWEBSTORE.md"
pause "Press Enter after listing fields and graphics are filled (not submitted)."

# ── 8. Privacy practices + permission justifications ─────────────────────
stage "Privacy practices + permission justifications"
say "Dashboard privacy form must match CHROMEWEBSTORE.md exactly."
step "Single purpose: Files browser tabs into native Chrome tab groups using the site, tab title, and user-written plain-language rules."
step "Declare local-only data; no remote Tab Organizer server; optional localhost Ollama only."
step "Paste Privacy Policy URL: ${CWS_PRIVACY_POLICY_URL:-"(from earlier stage)"}"
step "For each permission (tabs, tabGroups, storage, localhost hosts), paste the justification blocks from CHROMEWEBSTORE.md."
pause "Press Enter after privacy + justifications are saved as draft."

# ── 9. Final gate — human submit only ────────────────────────────────────
stage "Final gate — you submit (agent does not)"
say "Security code gate is clear. You still need privacy URL + screenshots."
step "Smoke-test: load dist/ unpacked → Organize this window → Rules → Local model off."
step "Confirm live privacy policy URL and ≥1 store-sized screenshot."
step "When ready: Developer Dashboard → Submit for review (manual)."
if confirm "I will submit myself only after privacy URL + screenshots are done"; then
  note "Good. Listing prep is done; submission stays manual."
else
  warn "Stop here. Do not submit yet."
fi

finish
say "Package: ${CWS_PACKAGE_ZIP:-$ZIP}"
say "Privacy URL: ${CWS_PRIVACY_POLICY_URL:-unset}"
say "Listing draft: $ROOT/CHROMEWEBSTORE.md"
warn "This wizard does not submit for you — click Submit only when ready."
}

run_wizard "$@"; exit
